import{_ as t,o as r,c as a,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"2016Q4 Ceph社区季度总结","description":"","frontmatter":{"title":"2016Q4 Ceph社区季度总结","date":"2016-12-01T00:00:00.000Z","tags":["Ceph","社区动态","技术发展"],"outline":"deep"},"headers":[],"relativePath":"quarterly/2016Q4_Ceph社区季度总结.md","filePath":"quarterly/2016Q4_Ceph社区季度总结.md","lastUpdated":1780459816000}'),n={name:"quarterly/2016Q4_Ceph社区季度总结.md"};function s(p,o,l,i,h,g){return r(),a("div",null,[...o[0]||(o[0]=[e('<h1 id="_2016年第四季度ceph社区活动与进展总结报告" tabindex="-1">2016年第四季度Ceph社区活动与进展总结报告 <a class="header-anchor" href="#_2016年第四季度ceph社区活动与进展总结报告" aria-label="Permalink to &quot;2016年第四季度Ceph社区活动与进展总结报告&quot;">​</a></h1><h2 id="日期-2016年11月" tabindex="-1">日期：2016年11月 <a class="header-anchor" href="#日期-2016年11月" aria-label="Permalink to &quot;日期：2016年11月&quot;">​</a></h2><hr><h2 id="一、本季度ceph社区的主要活动和重点议题" tabindex="-1">一、本季度Ceph社区的主要活动和重点议题 <a class="header-anchor" href="#一、本季度ceph社区的主要活动和重点议题" aria-label="Permalink to &quot;一、本季度Ceph社区的主要活动和重点议题&quot;">​</a></h2><p><strong>1. Ceph开发者月度会议</strong></p><p>在2016年第四季度，Ceph社区举行了定期开发者月度会议，其中一次会议的纪要如下：</p><ul><li><strong>会议时间</strong>： 2023年11月（具体日期未提及）</li><li><strong>参会人员</strong>： Sage、Adam、Erika、Nitin、Josh等</li><li><strong>会议主题</strong>： 分布式存储Ceph的开发进展、讨论议题及后续行动计划</li></ul><p><strong>2. 讨论议题</strong></p><ul><li><strong>内存池分配器信息</strong>： Sage介绍了新的内存池分配器，旨在解决内存碎片化问题，并通过统计内存分配情况来实现内存压力管理。</li><li><strong>Boost Pool和Slop Containers</strong>： 讨论了Boost Pool和Slop Containers的合并，以及确定使用场景。</li><li><strong>BD设备查询接口</strong>： Nitin介绍了为BD设备添加查询接口的计划。</li><li><strong>服务质量（QoS）更新</strong>： Josh介绍了使用DM Block算法实现QoS的计划。</li></ul><h2 id="二、技术发展和创新亮点" tabindex="-1">二、技术发展和创新亮点 <a class="header-anchor" href="#二、技术发展和创新亮点" aria-label="Permalink to &quot;二、技术发展和创新亮点&quot;">​</a></h2><p><strong>1. 内存池分配器</strong></p><p>新的内存池分配器通过宏定义实现对象在正确内存池中的分配，支持调试模式，旨在解决内存碎片化问题。</p><p><strong>2. Boost Pool和Slop Containers</strong></p><p>合并这两个组件，优化内存分配，提高性能。</p><p><strong>3. BD设备查询接口</strong></p><p>为BD设备添加查询接口，方便在RBD接口中查询BD设备的唯一ID等信息。</p><p><strong>4. 服务质量（QoS）更新</strong></p><p>使用DM Block算法实现QoS，为不同客户端提供服务质量保证。</p><h2 id="三、重要的决策和里程碑" tabindex="-1">三、重要的决策和里程碑 <a class="header-anchor" href="#三、重要的决策和里程碑" aria-label="Permalink to &quot;三、重要的决策和里程碑&quot;">​</a></h2><p><strong>1. 推进内存池分配器的开发，并进行性能分析。</strong></p><p><strong>2. 合并Boost Pool和Slop Containers，并确定使用场景。</strong></p><p><strong>3. 推进BD设备查询接口的开发。</strong></p><p><strong>4. 继续推进QoS算法的开发，并进行性能测试。</strong></p><h2 id="四、社区贡献和合作情况" tabindex="-1">四、社区贡献和合作情况 <a class="header-anchor" href="#四、社区贡献和合作情况" aria-label="Permalink to &quot;四、社区贡献和合作情况&quot;">​</a></h2><p>社区成员积极参与讨论、提出建议和贡献代码，共同推动Ceph的发展。</p><p><strong>1. 参与人员</strong>： Sage、Adam、Erika、Nitin、Josh等</p><p><strong>2. 贡献内容</strong>： 代码、性能分析、测试、讨论等</p><h2 id="五、下一季度的展望和计划" tabindex="-1">五、下一季度的展望和计划 <a class="header-anchor" href="#五、下一季度的展望和计划" aria-label="Permalink to &quot;五、下一季度的展望和计划&quot;">​</a></h2><p><strong>1. 继续推进现有项目的开发，包括内存池分配器、Boost Pool和Slop Containers、BD设备查询接口、QoS更新等。</strong></p><p><strong>2. 关注蓝鲸存储（Blue Store）的开发进展。</strong></p><p><strong>3. 鼓励开发者积极参与蓝图讨论，并提前在Wiki上进行讨论。</strong></p><p><strong>4. 举办下一季度Ceph开发者月度会议，讨论蓝图和开发进展。</strong></p><hr><p>本报告总结了2016年第四季度Ceph社区的活动、技术发展、决策和展望，旨在帮助社区成员了解Ceph的最新进展和未来方向。</p>',34)])])}const c=t(n,[["render",s]]);export{_ as __pageData,c as default};
